// Coalesce events without letting a busy generation stream postpone updates forever.
function createLiveUpdates({refresh,onError=()=>{},events=new EventSource('/api/events'),doc=document,clock=globalThis}){
  let timer=null,running=false,pending=false,disposed=false,failed=false;
  const visible=()=>doc.visibilityState!=='hidden';
  async function flush(){
    timer=null;
    if(disposed||running||!pending||!visible())return;
    pending=false;running=true;
    try{await refresh();failed=false;}catch(error){if(!failed)onError(error);failed=true;}
    finally{running=false;if(pending&&!disposed&&visible())schedule();}
  }
  function schedule(){
    if(disposed)return;
    pending=true;
    if(timer===null&&!running&&visible())timer=clock.setTimeout(flush,250);
  }
  const visibility=()=>{if(visible())schedule();};
  events.addEventListener('change',schedule);
  events.addEventListener('open',schedule); // Also catches missed completions after reconnecting.
  doc.addEventListener('visibilitychange',visibility);
  const poll=clock.setInterval(schedule,10000);
  return {events,dispose(){disposed=true;clock.clearTimeout(timer);clock.clearInterval(poll);events.close();doc.removeEventListener('visibilitychange',visibility);}};
}
