function frameQueueRows(jobs){return jobs.length?`<section class="frame-queue-section"><h2>Frame generation <span class="number-label">${jobs.length}</span></h2><div class="job-list">${jobs.map(j=>`<article class="job-row frame-job-row"><span class="job-icon ${j.status==='ready'?'succeeded':j.status}">${icon(j.status==='ready'?'check':j.status==='running'?'spark':j.status==='failed'?'refresh':'clock')}</span><div class="job-info"><strong><a href="#frames/${j.set_id}">${esc(j.frame_name)}</a></strong><span>Frame generation · ${friendlyDate(j.created_at)}${j.retry_count?' · retry '+j.retry_count:''}</span>${j.progress?`<p class="frame-task-progress">${esc(j.progress)}</p>`:''}${j.error?`<p class="error-copy">${esc(j.error.slice(-1200))}</p>`:''}</div><span class="badge ${j.status==='ready'?'succeeded':j.status}">${j.status==='running'?'<i class="spinner"></i>':''}${{ready:'Done',running:'Generating',queued:j.not_before?'Waiting to retry':'Waiting',failed:'Needs attention',cancelled:'Cancelled'}[j.status]||esc(j.status)}</span>${state.bootstrap.frame_queue?`<button class="button small" data-action="frame-job-logs" data-id="${j.id}">View progress</button>`:''}<a class="button small" href="#frames/${j.set_id}">Open frame</a></article>`).join('')}</div></section>`:'';}
async function showFrameLogs(id){state.frameLogJob=id;modal('Frame generation progress','<div id="frame-job-progress">Loading frame progress…</div>',true);await updateFrameLogs();}
async function updateFrameLogs(){const id=state.frameLogJob,el=$('#frame-job-progress');if(!id||!el)return;try{const job=await api('/api/frame-jobs/'+id);if(state.frameLogJob!==id||!el.isConnected)return;el.innerHTML=`<h3>${esc(job.frame_name)}</h3><p><strong>${esc(job.status==='ready'?'Complete':job.status)}</strong> · ${esc(job.progress||'Waiting for progress')}</p>${job.error?`<p class="error-copy">${esc(job.error)}</p>`:''}<a class="button small" href="#frames/${job.set_id}" data-action="close-modal">Open frame</a><details><summary>Detailed generation and validation log</summary><pre class="frame-task-log">${esc(job.log||'No log output yet.')}</pre></details>`;}catch(error){if(el.isConnected)el.textContent=error.message;}}
function renderQueue(){
  const frameJobs=state.frameJobs||[],active=state.jobs.filter(j=>j.status==='running').length+frameJobs.filter(j=>j.status==='running').length,queued=state.jobs.filter(j=>j.status==='queued').length+frameJobs.filter(j=>j.status==='queued').length;
  $('#content').innerHTML=`<section class="deck-heading"><div><span class="eyebrow">BACKGROUND TASKS</span><h1>Generation queue</h1><p>Card illustrations and frame generation, with live progress and saved task history.</p></div><div class="queue-controls">${[['codex','Codex workers'],['grok-cli','Grok workers']].map(([provider,label])=>`<label>${label}<select data-provider-concurrency="${provider}" aria-label="${label}">${[1,2,3,4].map(n=>`<option value="${n}" ${n===(state.bootstrap.provider_concurrency?.[provider]||state.bootstrap.concurrency||1)?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<button class="button ${state.bootstrap.paused?'primary':''}" data-action="pause-queue">${icon(state.bootstrap.paused?'play':'pause')}${state.bootstrap.paused?'Resume cards':'Pause cards'}</button></div></section><div class="queue-stats"><span><i class="status-dot online"></i>${active} generating</span>${[['codex','Codex'],['grok-cli','Grok']].map(([provider,label])=>`<span>${label}: ${state.jobs.filter(j=>j.status==='running'&&j.type!=='compose'&&j.generation_provider===provider).length} / ${state.bootstrap.provider_concurrency?.[provider]||state.bootstrap.concurrency||1}</span>`).join('')}<span>${icon('clock')}${queued} waiting</span><span>${state.jobs.filter(j=>j.status==='succeeded').length+frameJobs.filter(j=>j.status==='ready').length} completed</span>${state.bootstrap.paused?'<span class="badge queued">Queue paused</span>':''}</div>${Object.entries(state.bootstrap.provider_cooldowns||{}).map(([provider,until])=>`<div class="rate-limit-notice">${icon('clock')} ${provider==='grok-cli'?'Grok':'Codex'} is rate limited. Its jobs will retry after ${esc(new Date(until).toLocaleString())}. Other providers can continue.</div>`).join('')}${frameQueueRows(frameJobs)}<div class="job-list">${state.jobs.length?state.jobs.map(j=>`<article class="job-row job-row-link" data-action="open-job-card" data-deck="${j.deck_id}" data-card="${j.card_id}" ${j.status==='succeeded'&&j.version_id?`data-version="${j.version_id}"`:''} title="Show in deck"><span class="job-icon job-card ${j.status}">${j.status==='succeeded'&&j.version_id?`<img loading="lazy" src="${imageUrl(j.version_id,'thumb')}" alt="">`:icon(j.status==='succeeded'?'check':j.status==='running'?'spark':j.status==='failed'?'refresh':'clock')}</span><div class="job-info"><strong><a href="#deck/${j.deck_id}" data-action="open-job-card" data-deck="${j.deck_id}" data-card="${j.card_id}" ${j.status==='succeeded'&&j.version_id?`data-version="${j.version_id}"`:''}>${esc(j.card_name)}${j.variant_index?` · art ${j.variant_index}`:''}</a></strong><span><a href="#deck/${j.deck_id}">${esc(state.decks.find(d=>d.id===j.deck_id)?.name||'Deck')}</a>${j.art_set_name?` · ${esc(j.art_set_name)}`:''} · ${j.type==='revise'?'Revision':j.type==='compose'?'Appearance update':'New illustration'}${j.type!=='compose'&&j.generation_provider?` · ${artBy(j.generation_provider)}`:''} · ${friendlyDate(j.created_at)}</span>${j.error?`<p class="error-copy">${esc(j.error.slice(-300))}</p>`:''}</div><span class="badge ${j.status}">${j.status==='running'?'<i class="spinner"></i>':''}${j.waiting_for_commander?'Waiting for commander':j.not_before&&j.status==='queued'?'Waiting to retry':{succeeded:'Done',running:'Generating',queued:'Waiting',failed:'Needs attention',cancelled:'Cancelled'}[j.status]||j.status}</span><button class="button small" data-action="job-logs" data-id="${j.id}">View progress</button>${['failed','cancelled'].includes(j.status)?`<button class="icon-button" data-action="retry-job" data-id="${j.id}" aria-label="Retry ${esc(j.card_name)}">${icon('refresh')}</button>`:['queued','running'].includes(j.status)?`<button class="icon-button" data-action="cancel-job" data-id="${j.id}" aria-label="Cancel ${esc(j.card_name)}">${icon('close')}</button>`:''}</article>`).join(''):`<div class="empty-state">${icon('spark')}<h3>${frameJobs.length?'No card jobs':'A little quiet in the studio'}</h3><p>Generate a deck or request a card revision to start a new illustration.</p><a class="button" href="#library">Open my decks</a></div>`}</div>`;
}
function renderContent(){if(state.view==='print'){if(!state.printUI)state.printUI=new PrintStudio($('#content'),{api,toast,decks:state.decks,onPrint:tray=>{state.printTrayItems=tray.items.map(i=>({id:i.id,quantity:i.quantity}));return printDeck(null,null,true);}});return;}if(state.view==='official-printings'){if(!state.printingUI)state.printingUI=new OfficialPrintingPicker($('#content'),{api,toast,cardId:state.printingCardId,deckId:state.deckId});return;}if(state.view==='chat'){if(!state.chatUI)state.chatUI=new ChatStudio($('#content'),{api,toast,decks:state.decks});return;}if(['styles','style-detail','deck-guidelines'].includes(state.view)){void renderStylePage();return;}if(state.view!=='frame-detail'){state.frameEditor?.dispose();state.frameEditor=null;}if(state.view==='deck'&&state.deck)renderDeck();else if(state.view==='queue')renderQueue();else if(state.view==='frames')renderFrames();else if(state.view==='frame-templates')renderFrameTemplates();else if(state.view==='frame-detail')renderFrameDetail();else renderLibrary();}
function modal(title,content,wide=false){$('#modal-root').innerHTML=`<dialog id="modal" class="modal ${wide?'wide':''}"><div class="modal-heading"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>${content}</dialog>`;$('#modal').showModal();$('#modal').addEventListener('cancel',()=>{state.logJob=null;state.frameDetail=null;});setTimeout(()=>$('#modal [autofocus]')?.focus(),0);}
function closeModal(){state.frameLogJob=null;state.logJob=null;state.frameDetail=null;$('#modal')?.close();$('#modal-root').innerHTML='';}
const sectionName=section=>({main:'Main',commander:'Commander',sideboard:'Sideboard',tokens:'Tokens'})[section]||section;
function replacePreview(plan){
  const list=(title,rows,line,open=false)=>rows.length?`<details class="replace-group" ${open?'open':''}><summary>${title} <span>${rows.length}</span></summary><ul>${rows.map(line).join('')}</ul></details>`:'';
  const change=c=>[c.from.quantity!==c.to.quantity?`${c.from.quantity} → ${c.to.quantity} copies`:'',c.from.section!==c.to.section?`${sectionName(c.from.section)} → ${sectionName(c.to.section)}`:''].filter(Boolean).join(' · ');
  return `<div class="replace-totals"><span><strong>${plan.kept}</strong> kept · ${plan.kept_art} with art</span><span><strong>${plan.added.length}</strong> added</span><span><strong>${plan.removed.length}</strong> removed</span>${plan.tokens_kept?`<span><strong>${plan.tokens_kept}</strong> tokens kept</span>`:''}</div>
    ${plan.blocked.length?`<p class="replace-warning">Cancel generation for ${esc(plan.blocked.join(', '))} before replacing the list.</p>`:''}
    ${list('Removed',plan.removed,c=>`<li>${c.quantity} ${esc(c.name)} <small>${sectionName(c.section)}${c.has_art?` · has artwork (${c.versions} version${c.versions===1?'':'s'})`:''}</small></li>`,true)}
    ${list('Added',plan.added,c=>`<li>${c.quantity} ${esc(c.name)} <small>${sectionName(c.section)}</small></li>`)}
    ${list('Changed',plan.changed,c=>`<li>${esc(c.name)}${c.variant_index?` (variant ${c.variant_index})`:''} <small>${change(c)}</small></li>`)}`;
}

function generationInputs({history=true,references=true,isolated=true,showHistory=true,revision=false,visible=true}={}){
 return `<fieldset class="generation-inputs" ${visible?'':'hidden'}><legend>Generation inputs</legend>${showHistory?`<label class="checkbox-label"><input ${revision?'id="include-generation-history"':''} name="include_history" type="checkbox" ${history?'checked':''}> Include previous artwork</label><p class="field-hint">Turn off to start from scratch. Earlier versions stay saved.</p>`:'<input name="include_history" type="hidden" value="false">'}<label class="checkbox-label"><input ${revision?'id="use-generation-references"':''} name="use_reference_images" type="checkbox" ${references?'checked':''}> Use deck reference images</label><p class="field-hint">Include uploaded character and art-style images.</p><label class="checkbox-label"><input ${revision?'id="isolate-generation"':''} name="isolate_generation" type="checkbox" ${isolated?'checked':''}> Isolate generation workspace</label><p class="field-hint">Block filesystem access to the live library and unrelated styles. Only selected inputs and newly generated peers from this batch enter the workspace.</p><p class="field-hint">For a clean style test, exclude previous artwork and reference images, and keep isolation on.</p></fieldset>`;
}
function readGenerationInputs(form){return {include_history:form.elements.generation_type?form.elements.generation_type.value==='continuity':form.elements.include_history?.type==='checkbox'?form.elements.include_history.checked:false,use_reference_images:form.elements.use_reference_images.checked,isolate_generation:form.elements.isolate_generation.checked};}
const OFFICIAL_PREFERENCES=[['newest','Newest printing'],['oldest','Original printing (oldest)'],['default','Most typical printing'],['atypical','Most unusual printing'],['promo','Promo printing'],['usd-low','Cheapest printing (USD)'],['usd-high','Most expensive printing (USD)'],['notub','Avoid Universes Beyond']];
const OFFICIAL_TREATMENTS=[['any','Any treatment'],['borderless','Borderless'],['fullart','Full art'],['extendedart','Extended art'],['showcase','Showcase'],['retro','Retro frame (1993/1997)'],['textless','Textless']];
const officialChoiceLabel=r=>[r.prefer&&r.prefer!=='newest'?OFFICIAL_PREFERENCES.find(([v])=>v===r.prefer)?.[1]:'',r.treatment&&r.treatment!=='any'?OFFICIAL_TREATMENTS.find(([v])=>v===r.treatment)?.[1]:''].filter(Boolean).join(' · ');
function populateDialog(){
 const blanks=state.deck.cards.filter(c=>!c.active_version_id&&!['queued','running'].includes(c.job_status)&&!(c.art_mode==='official'&&c.printing_json!=='{}'&&!c.printing_error)).length,prefer=storedPreference('official-prefer','newest'),treatment=storedPreference('official-treatment','any'),quality=storedPreference('official-quality','max'),options=(list,value)=>list.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
 modal('Populate MTG art',`<form id="populate-mtg-art-form"><p class="form-intro">Fill up to ${blanks} blank card${blanks===1?'':'s'} in this artwork set with official Scryfall scans. Existing artwork and cards that are generating are left alone.</p><div class="form-row"><label>Prefer<select name="prefer">${options(OFFICIAL_PREFERENCES,prefer)}</select></label><label>Art treatment<select name="treatment">${options(OFFICIAL_TREATMENTS,treatment)}</select></label><label>Image quality<select name="quality">${options([['max','Maximum available (PNG preferred)'],['large','Large JPEG'],['normal','Standard JPEG']],quality)}</select></label></div><p class="field-hint">Scryfall picks the preferred printing for each card. If no printing has the chosen treatment, the preferred printing without it is used, then the newest available one. English scans are tried before other languages. Maximum quality downloads the native PNG when available, otherwise the largest supported scan; it does not upscale images.</p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Populate MTG art</button></div></form>`);
}
function swapMtgArtDialog(){
 const cards=state.deck.cards.filter(c=>c.active_version_id&&['official','reconstructed'].includes(c.art_mode)&&!['queued','running'].includes(c.job_status)),scans=cards.filter(c=>c.art_mode==='official').length,prefer=storedPreference('swap-prefer','oldest'),treatment=storedPreference('swap-treatment','any'),quality=storedPreference('official-quality','max'),format=storedPreference('swap-format','keep'),options=(list,value)=>list.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
 modal('Swap MTG art',`<form id="swap-mtg-art-form"><p class="form-intro">Re-pick the printing for all ${cards.length} card${cards.length===1?'':'s'} that use real MTG art in this artwork set (${scans} original scan${scans===1?'':'s'}, ${cards.length-scans} reconstructed). Each card keeps its current image until the new one is saved; earlier versions stay in history. Custom artwork and cards that are generating are left alone.</p><div class="form-row"><label>Prefer<select name="prefer">${options(OFFICIAL_PREFERENCES,prefer)}</select></label><label>Art treatment<select name="treatment">${options(OFFICIAL_TREATMENTS,treatment)}</select></label></div><div class="form-row"><label>Card format<select name="format">${options([['keep','Keep each card’s current format'],['official','Original MTG scan'],['reconstructed','Reconstructed MTG (official art, rendered text)']],format)}</select></label><label>Image quality<select name="quality">${options([['max','Maximum available (PNG preferred)'],['large','Large JPEG'],['normal','Standard JPEG']],quality)}</select></label></div><p class="field-hint">Scryfall picks the preferred printing for each card, with the same fallbacks as Populate MTG art. Cards already on the chosen printing and format are left unchanged. Layouts without a reconstruction template keep an original scan. To replace real MTG art with custom illustrations instead, use Generate missing.</p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">Swap ${cards.length} card${cards.length===1?'':'s'}</button></div></form>`);
}
function generationDialog({mode='all',card_ids=null,retry=null,options=null}={}){
 state.generationRequest={mode,card_ids,retry};const fresh=mode==='all'||mode==='selected',defaults=options||{include_history:!fresh,use_reference_images:!fresh,isolate_generation:true};
 const candidates=state.deck?.cards.filter(c=>c.art_mode!=='official'&&(!card_ids||card_ids.includes(c.id))&&!['queued','running'].includes(c.job_status)&&(mode!=='missing'||!c.active_version_id))||[];
 modal(retry?'Retry card generation':mode==='all'?'Regenerate all cards':mode==='selected'?'Generate selected cards':'Generate missing cards',`<form id="generation-form"><p class="form-intro">${retry?'Review the saved inputs before trying this card again.':`Queue ${candidates.length} card${candidates.length===1?'':'s'} using the current deck guidelines. Earlier versions stay available. The commander generates first when included. New cards from this run share a read-only consistency gallery; older runs are excluded. Cards using official printings are skipped.`}</p><fieldset class="generation-presets"><legend>Generation type</legend><label class="checkbox-label"><input type="radio" name="generation_type" value="fresh" ${!defaults.include_history?'checked':''}> Fresh artwork</label><label class="checkbox-label"><input type="radio" name="generation_type" value="continuity" ${defaults.include_history?'checked':''}> Use previous artwork as reference</label></fieldset>${generationInputs({history:defaults.include_history,references:defaults.use_reference_images,isolated:defaults.isolate_generation,showHistory:false})}<div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${retry?'Retry generation':'Start generation'}</button></div></form>`);
}
function swapDialog(card){
 const bench=state.deck.cards.filter(c=>c.section==='sideboard'&&c.entry_kind!=='token'&&c.id!==card.id),copies=`${card.quantity} ${card.quantity===1?'copy':'copies'}`;
 modal('Swap out '+card.name,`<form id="swap-card-form" data-card="${card.id}"><p class="form-intro">The new card takes this slot: ${esc(sectionName(card.section))} · ${copies}.</p><label>Swap in<input name="name" required maxlength="180" autocomplete="off" list="swap-bench" placeholder="Swords to Plowshares" autofocus></label><datalist id="swap-bench">${bench.map(c=>`<option value="${esc(c.name)}">`).join('')}</datalist><p class="field-hint">${bench.length?'Pick a sideboard card to bring it back with its artwork, or type any card name.':'Type any card name.'}</p>${card.section!=='sideboard'?`<fieldset class="generation-presets"><legend>${esc(card.name)}</legend><label class="checkbox-label"><input type="radio" name="keep_old" value="sideboard" checked> Move to the sideboard and keep its artwork</label><label class="checkbox-label"><input type="radio" name="keep_old" value="remove"> Remove from the deck</label></fieldset>`:''}<label class="checkbox-label"><input name="generate" type="checkbox" checked> Generate artwork for the new card</label><p class="field-hint">Skipped when the card returns from the sideboard with artwork.</p><details><summary>Generation options</summary>${generationInputs({history:false,references:true,isolated:true,showHistory:false})}</details><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${icon('swap')} Swap card</button></div></form>`);
}
function newArtworkSet(){modal('Create an artwork set',`<form id="art-set-form"><p class="form-intro">Keep the deck’s shared card list and give it another complete art direction. Creating this set switches the editor to it.</p><label>Artwork set name<input name="name" required maxlength="120" placeholder="Watercolour edition" autofocus></label><label>Starting artwork<select name="mode"><option value="fresh">Start fresh — generate new art for every card</option><option value="copy">Copy the current art and version history</option></select></label><label>Style guidelines<select name="guidelines" id="new-art-set-guidelines"><option value="fresh">Write a new style guide</option><option value="copy">Copy the current guidelines and references</option></select></label><label data-art-set-guide>Style guide<textarea name="style" rows="7" maxlength="50000" placeholder="Describe the art direction for this set. Blank uses the neutral default."></textarea><span class="field-hint">You can edit the complete guide, reusable style and reference images with the Style button after creating the set.</span></label><p class="field-hint">Copied art is shared until revised; revisions stay in this set. Frame and image provider start with the current settings and can be changed independently.</p><div class="form-actions"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Create artwork set</button></div></form>`);}
function newDeck(){modal('Start a new adventure',`<form id="new-deck-form"><p class="form-intro">Give your deck a name, paste its cards, and let your studio bring it to life.</p><label>Deck name<input name="name" required maxlength="120" placeholder="My Commander Deck" autofocus></label><div class="form-row"><label>Collection<input name="folder" maxlength="80" placeholder="Commander decks" list="folders"></label><label>Description<input name="description" maxlength="4000" placeholder="The theme or strategy you have in mind…"></label></div><datalist id="folders">${[...new Set(state.decks.map(d=>d.folder).filter(Boolean))].map(f=>`<option value="${esc(f)}">`).join('')}</datalist><label>Decklist<textarea name="decklist" id="new-decklist" rows="8" placeholder="Commander&#10;1 Your Commander&#10;&#10;Deck&#10;1 Sol Ring&#10;1 Arcane Signet&#10;10 Island"></textarea></label><div id="parse-summary" class="parse-summary">Accepts plain lists and exact printings: 1 Sol Ring (CMM) 410 or 1 x Sol Ring CMM 410. Set + collector number imports official art; plain names use custom art.</div><section class="style-editor"><h3>${icon('leaf')} Card style guidelines</h3><p>Describe this deck’s visual world, art medium, colours, composition, alternate-title rules and flavour text. Paste a complete style brief here, or leave blank for the neutral default.</p><label class="sr-only" for="new-deck-style">Card style guidelines</label><textarea id="new-deck-style" name="style" rows="7" maxlength="50000" placeholder="Theme and subjects:…&#10;Medium and palette:…&#10;Composition:…&#10;Card naming and flavour text:…"></textarea></section>${state.bootstrap?.styles_enabled?`<label>Reusable art style<select name="style_revision_id"><option value="">Use the deck prompt</option>${(state.artStyles||[]).filter(s=>!s.archived).map(s=>`<option value="${s.current_revision_id}">${esc(s.name)} · revision ${s.revision_number}</option>`).join('')}</select></label><p class="field-hint">Art technique comes from the selected Style. The deck prompt still defines the subjects, world and naming.</p>`:''}<label class="checkbox-label"><input name="deduplicate" type="checkbox" checked> Skip cards already in this deck</label><p class="field-hint">Artwork is unique to this deck by default. You can explicitly choose artwork from another deck later.</p><label class="checkbox-label"><input name="generate" type="checkbox" checked> Start generating after import</label>${generationInputs({history:false,showHistory:false})}<div class="form-actions"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">${icon('spark')} Create deck</button></div></form>`,true);}
function providerMenuItems(deck){const providers=state.bootstrap?.image_providers;if(!providers?.length)return [];const current=deck.image_provider||'codex';return ['<hr>','<p class="menu-note">Illustrate new cards with</p>',...providers.map(p=>menuItem('set-provider',`${esc(p.name)}${p.available===false?' · sign in required':''}`,p.id===current?'check':'',`data-provider="${esc(p.id)}" aria-checked="${p.id===current}" role="menuitemradio" ${p.available===false?'disabled':''} ${p.id===current?'':'data-unchecked'}`)),'<hr>'];}
function imageProviderControl(deck,id){
  const providers=state.bootstrap?.image_providers;if(!providers?.length)return '';
  return `<label class="sort-control">Generation provider<select id="${id}" name="image_provider" aria-label="Generation provider">${providers.map(p=>`<option value="${esc(p.id)}" ${p.id===(deck.image_provider||'codex')?'selected':''} ${p.available===false?'disabled':''}>${esc(p.name)}${p.available===false?' · sign in required':''}</option>`).join('')}</select></label>`;
}
function deckSettings(){const d=state.deck;modal('Deck details',`<form id="deck-settings-form">${imageProviderControl(d,'settings-image-provider')}<label>Deck name<input name="name" value="${esc(d.name)}" required maxlength="120"></label><div class="form-row"><label>Collection<input name="folder" value="${esc(d.folder)}" maxlength="80"></label><label>Description<input name="description" value="${esc(d.description)}" maxlength="4000"></label></div>${state.bootstrap?.styles_enabled?'<p class="field-hint">Art direction, reusable Styles and references are managed on the deck guidelines page.</p><button type="button" class="button" data-action="deck-style">Edit style guidelines</button>':`<label>Card style guidelines<textarea name="style" rows="8" maxlength="50000" placeholder="Uses the neutral fantasy style when left blank">${esc(d.style)}</textarea></label><p class="field-hint">New generations and revisions use this direction. Existing card images stay as they are.</p>`}<div class="form-actions"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Save details</button></div></form>`);}
function deckStyle(){
  const d=state.deck;if(state.bootstrap?.styles_enabled){closeModal();location.hash='deck/'+d.id+'/guidelines';return;}
  modal('Card style guidelines',`<form id="deck-style-form"><p class="form-intro">Set the visual world for ${esc(d.name)}. Include theme, subjects, illustration medium, palette, composition, naming and flavour-text requirements.</p><label for="deck-style-text">Deck guidelines<textarea id="deck-style-text" name="style" rows="16" maxlength="50000" autofocus placeholder="Describe the style you want for this deck…">${esc(d.style||'')}</textarea></label><details class="style-details"><summary>Neutral default guidelines</summary><pre class="style-preview">${esc(state.bootstrap.default_style||'')}</pre></details><p class="field-hint">Blank uses the neutral default. Saved changes apply to jobs queued afterwards; already queued jobs retain their saved guidelines. Use Generate selected or a revision request to update an existing card.</p><div class="form-actions"><button class="button" type="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Save guidelines</button></div></form>`,true);
}
function artVariants(card=null,requestedKind=null){
  const lands=['Plains','Island','Swamp','Mountain','Forest','Wastes',...['Plains','Island','Swamp','Mountain','Forest'].map(n=>'Snow-Covered '+n)];
  const kind=requestedKind||(card?.entry_kind==='token'?'token':lands.includes(card?.name)?'land':card?'card':'token');
  const spec=card?.token_spec||{type_line:'Token Creature — Cat',colors:['G'],power:'1',toughness:'1',oracle_text:''};
  modal(requestedKind?{land:'Add basic lands',token:'Add tokens',card:'Add card art variants'}[requestedKind]:'Tokens & unique art variants',`<form id="variants-form"><p class="form-intro">Choose a token or card, then decide how many different illustrations to create.</p><label ${requestedKind?'hidden':''}>Entry kind<select name="kind" id="variant-kind">${[['token','Token'],['land','Basic land'],['card','Other card']].map(([v,label])=>`<option value="${v}" ${kind===v?'selected':''}>${label}</option>`).join('')}</select></label>
    <label id="variant-land-field">Basic land<select name="land_name" id="variant-land-name">${lands.map(n=>`<option ${n===(card?.name||'Forest')?'selected':''}>${n}</option>`).join('')}</select></label>
    <label id="variant-name-field">Original card / token name<input name="name" id="variant-name" value="${esc(card?.name||(kind==='card'?'':'Cat'))}" maxlength="180"></label>
    <section id="token-fields"><label>Token preset<select id="token-preset"><option value="custom" ${card?'selected':''}>Custom token</option><option value="cat" ${card?'':'selected'}>1/1 green Cat · Rin and Seri</option><option value="dog">1/1 white Dog · Rin and Seri</option></select></label><div id="token-summary" class="token-summary"></div><details id="token-details"><summary>Customise token details</summary><label>Type line<input name="type_line" id="token-type" value="${esc(spec.type_line||'Token Creature — Cat')}" maxlength="180"></label><div class="form-row"><label>Colours · W, U, B, R, G<input name="colors" id="token-colors" value="${esc((spec.colors||[]).join(', '))}" placeholder="Blank = colourless"></label><label>Power / toughness<div class="token-stats"><input name="power" id="token-power" value="${esc(spec.power||'')}" maxlength="12" aria-label="Token power"><span>/</span><input name="toughness" id="token-toughness" value="${esc(spec.toughness||'')}" maxlength="12" aria-label="Token toughness"></div></label></div><label>Token rules<textarea name="oracle_text" rows="3" maxlength="5000">${esc(spec.oracle_text||'')}</textarea></label><p class="field-hint">Specify the exact token characteristics. All art variants in this batch use these same rules and stats. Tokens are kept outside your main-deck count.</p></details></section>
    <div class="form-row"><label>Unique illustrations<input name="variants" id="variant-count" type="number" min="1" max="100" value="6" required></label><label>Total physical copies<input name="total_copies" id="variant-total" type="number" min="1" max="999" value="${card?.quantity||6}" required></label></div><p id="variant-allocation" class="field-hint"></p><label class="checkbox-label" id="variant-split-field"><input name="replace_existing" id="variant-split" type="checkbox" ${requestedKind?'':'checked'}> Split existing copies instead of adding more</label><p id="variant-existing-note" class="field-hint"></p><label class="checkbox-label"><input name="generate" type="checkbox"> Generate artwork now</label>${generationInputs({history:false,showHistory:false,visible:false})}<div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancel</button><button class="button primary" type="submit">Create art variants</button></div></form>`,true);
  updateVariantForm();updateVariantSummary();
}
function updateVariantForm(){
  const form=$('#variants-form');if(!form)return;const kind=form.elements.kind.value;
  $('#variant-land-field').hidden=kind!=='land';$('#variant-name-field').hidden=kind==='land';$('#token-fields').hidden=kind!=='token';$('#variant-split-field').hidden=kind==='token';
  form.elements.name.required=kind!=='land';form.elements.type_line.required=kind==='token';
  const name=kind==='land'?form.elements.land_name.value:form.elements.name.value;
  const existing=state.deck.cards.find(c=>c.name.toLowerCase()===name.trim().toLowerCase()&&c.section==='main'&&!c.variant_group);
  $('#variant-existing-note').textContent=kind==='token'?'':existing?`${existing.quantity} existing copies. The first variant keeps its current image and history; remaining variants get fresh art.`:'No ungrouped entry to split. These variants will be added as new copies.';
  if(kind!=='token'&&existing&&form.elements.replace_existing.checked){form.elements.total_copies.value=existing.quantity;form.elements.variants.value=Math.min(Number(form.elements.variants.value),existing.quantity);}
}
function updateVariantSummary(){
 const form=$('#variants-form');if(!form)return;
 const token=form.elements.kind.value==='token',preset=$('#token-preset').value;
 $('#variant-name-field').hidden=form.elements.kind.value==='land'||token&&preset!=='custom';
 $('#token-details').open=token&&preset==='custom';
 $('#token-summary').textContent=token?`${form.elements.power.value||'—'}/${form.elements.toughness.value||'—'} ${form.elements.name.value} · ${form.elements.colors.value.split(/[ ,]+/).filter(Boolean).map(c=>({W:'White',U:'Blue',B:'Black',R:'Red',G:'Green'}[c.toUpperCase()]||c)).join(' / ')||'Colourless'}`:'';
 const variants=Number(form.elements.variants.value),copies=Number(form.elements.total_copies.value);
 $('#variant-allocation').textContent=variants>0&&copies>=variants?`${variants} unique illustrations · ${copies} total copies · ${copies%variants?Math.floor(copies/variants)+'–'+Math.ceil(copies/variants):copies/variants} ${copies/variants===1?'copy':'copies'} per illustration`:'Total copies must be at least the number of unique illustrations.';
}
function printSettings(){
  const form=$('#print-form'),values=Object.fromEntries(new FormData(form));
  for(const name of ['landscape','quantities','include_tokens','include_sideboard','crop_marks','calibration','skip_missing'])values[name]=form.elements[name]?.checked??false;
  delete values.print_card;
  if(!state.printTarget&&values.print_scope==='selected')values.card_ids=[...form.querySelectorAll('[name=print_card]:checked')].map(el=>el.value);
  if(!state.printTarget&&state.printDeckContext)values.art_set_id=state.printDeckContext.artSetId;
  if(state.printTarget){values.card_ids=[state.printTarget.cardId];values.version_id=state.printTarget.versionId;values.copies=Number(values.copies);values.art_set_id=state.printTarget.artSetId;}
  if(state.printTray){values.items=state.printTrayItems;delete values.card_ids;delete values.art_set_id;delete values.version_id;}
  return values;
}
async function printDeck(target=null,selection=null,tray=false){
  state.printTray=tray;
  state.printTarget=target;state.printDeckContext=(target||tray)?null:{deckId:state.deck.id,artSetId:state.deck.active_art_set_id};const single=!!target,selected=new Set(selection||[...state.selected]),cards=state.deck?.cards||[];
  const choose=cards.some(c=>selected.has(c.id));
  const scope=(single||tray)?'':`<fieldset class="print-scope"><legend>Cards to print</legend><label class="checkbox-label"><input type="radio" name="print_scope" value="all" ${choose?'':'checked'}> Whole deck</label><label class="checkbox-label"><input type="radio" name="print_scope" value="selected" ${choose?'checked':''}> Choose cards</label></fieldset><details class="print-card-picker" data-print-cards ${choose?'open':'hidden'}><summary>Choose individual cards</summary><input type="search" data-print-search placeholder="Find cards to print…" aria-label="Find cards to print"><div class="print-card-actions"><button type="button" class="text-button" data-action="print-select-shown">Select shown</button><button type="button" class="text-button" data-action="print-select-none">Clear selection</button></div><div class="print-card-list">${cards.map(c=>`<label class="print-card-choice" data-print-card-name="${esc(c.name.toLowerCase())}"><input type="checkbox" name="print_card" value="${c.id}" ${selected.has(c.id)&&c.active_version_id?'checked':''} ${c.active_version_id?'':'disabled'}><span>${esc(c.name)}<small>${c.active_version_id?`${c.quantity} in deck · ${esc(c.section)}`:'No image yet'}</small></span></label>`).join('')}</div></details>`;
  modal(tray?'Print your tray':single?'Print '+target.name:'Print your deck',`<form id="print-form"><p class="form-intro">${single?`Print only ${esc(target.name)} · version ${target.number}. Starts with one copy, independent of the deck quantity.`:'Export the selected versions as a PDF at their exact physical size.'}</p>${scope}<div class="print-settings-grid">${single?'<label>Copies<input name="copies" type="number" value="1" min="1" max="999" step="1" required></label>':''}<label>Paper<select name="paper"><option>A4</option><option>Letter</option><option>A3</option><option>Custom</option></select></label><label>Card faces<select name="face_mode"><option value="fronts">Fronts only</option><option value="backs" ${single&&!target.hasBack?'disabled':''}>Double-faced backs only</option><option value="separate">Each face as a separate card</option><option value="duplex" ${single&&!target.hasBack?'disabled':''}>Paired duplex pages</option></select></label><label>Duplex flip edge<select name="duplex_edge"><option value="long">Long edge</option><option value="short">Short edge</option></select></label><label>PDF pages<input name="page_range" placeholder="All pages · e.g. 1, 3-5" maxlength="4000"></label><label>Download format<select name="packaging"><option value="combined">One combined PDF</option><option value="per_page">Individual PDFs · page links + ZIP</option></select></label><label>Image quality<select name="quality"><option value="full">Full resolution · preserve source</option><option value="1200">1200 PPI output</option><option value="600">600 PPI output</option><option value="compact">300 PPI · smaller files</option></select></label><label>Card width · mm<input type="number" name="card_width" value="63.5" min="20" max="150" step="0.1" required></label><label>Card height · mm<input type="number" name="card_height" value="88.9" min="20" max="200" step="0.1" required></label><label>Page margin · mm<input type="number" name="margin" value="5" min="0" max="100" step="0.1" required></label><label>Card spacing · mm<input type="number" name="gap" value="2" min="0" max="30" step="0.1" required></label><label>Bleed · mm<input type="number" name="bleed" value="0" min="0" max="5" step="0.1" required></label><label>Custom paper width · mm<input type="number" name="paper_width" value="210" min="100" max="1000" step="0.1"></label><label>Custom paper height · mm<input type="number" name="paper_height" value="297" min="100" max="1000" step="0.1"></label></div><div class="print-options"><label class="checkbox-label"><input type="checkbox" name="landscape"> Landscape</label>${single||tray?'':'<label class="checkbox-label"><input type="checkbox" name="quantities" checked> Include all copies</label><label class="checkbox-label"><input type="checkbox" name="include_tokens" checked> Include tokens</label><label class="checkbox-label"><input type="checkbox" name="include_sideboard"> Include sideboard</label>'}<label class="checkbox-label"><input type="checkbox" name="crop_marks" checked> Trim / crop marks</label><label class="checkbox-label"><input type="checkbox" name="calibration"> Add calibration page</label>${single||tray?'':'<label class="checkbox-label"><input type="checkbox" name="skip_missing"> Skip cards without images</label>'}</div><div id="print-preview" class="print-preview">Calculating sheet layout…</div><div id="print-download" hidden></div><p class="field-hint">Print at Actual size / 100%; disable Fit to page. Page numbers refer to the PDF after choosing cards and copies; duplex fronts and backs are separate pages. Choose “Each face as a separate card” to print both faces in their own card-sized spaces, cut them out and put them together in one sleeve. Print those sheets single-sided. Bleed extends edge pixels outside the trim. Individual PDFs provide Open &amp; print and Download links for each sheet, plus an optional ZIP. Duplex fronts and backs keep their original page numbers; automatic duplex requires the combined PDF. PDF output uses RGB; use your printer’s required colour settings.</p><div class="form-actions"><button type="button" class="button" data-action="print-preview">Update preview</button><button type="submit" class="button primary">${icon('download')} Prepare print files</button></div></form>`,true);
  await restorePrintHistory();
  await updatePrintPreview();
}
async function updatePrintPreview(){
  const form=$('#print-form');if(!form)return;
  showPrintDownload(null);
  try{
    const settings=printSettings(),signature=JSON.stringify(settings);
    const p=await api(state.printTray?'/api/print/preview':`/api/decks/${state.printTarget?.deckId||state.printDeckContext?.deckId||state.deck.id}/print-preview`,{method:'POST',body:settings});if($('#print-form')!==form||!$('#print-preview')||JSON.stringify(printSettings())!==signature)return;
    showPrintDownload(p.saved_export);
    const page=p.selected_pages?.[0]||1,isBack=p.face_mode==='duplex'&&page%2===0,sheet=p.face_mode==='duplex'?Math.floor((page-1)/2):page-1;
    const count=page>p.pages?0:Math.max(0,Math.min(p.per_page,p.count-sheet*p.per_page));
    const rects=Array.from({length:count},(_,i)=>{let column=i%p.columns,row=Math.floor(i/p.columns);if(isBack){if((p.height>=p.width)===(p.duplex_edge==='long'))column=p.columns-1-column;else row=p.rows-1-row;}const x=p.offset_x+column*(p.card_width+2*p.bleed+p.gap),y=p.offset_y+row*(p.card_height+2*p.bleed+p.gap);return `<rect x="${x}" y="${y}" width="${p.card_width+2*p.bleed}" height="${p.card_height+2*p.bleed}" rx="1"/>`;}).join('');
    $('#print-preview').innerHTML=`<svg class="print-sheet" viewBox="0 0 ${p.width} ${p.height}" aria-label="Layout of PDF page ${page}"><rect class="sheet-paper" width="${p.width}" height="${p.height}"/>${page>p.pages&&p.calibration?`<rect x="20" y="${p.height-130}" width="100" height="100"/>`:rects}</svg><div><strong>${p.count} ${p.face_mode==='separate'?'card faces':p.selected_pages?'copies in layout':'card copies'} · ${p.output_pages} PDF page${p.output_pages===1?'':'s'}</strong>${p.selected_pages?`<p>Pages ${esc(p.selected_pages.join(', '))} from ${p.total_pages} total</p>`:''}<p>${p.columns} columns × ${p.rows} rows · ${p.per_page} cards per sheet<br>${p.card_width} × ${p.card_height} mm trim<br>${p.width} × ${p.height} mm paper</p>${p.calibration?'<p>Includes a calibration page when selected.</p>':''}${p.missing.length?`<p class="error-copy">${p.missing.length} entries have no image: ${esc(p.missing.slice(0,5).join(', '))}${p.missing.length>5?'…':''}. Generate them or enable skipping.</p>`:''}</div>`;
  }catch(e){if($('#print-preview'))$('#print-preview').textContent=e.message;}
}
async function downloadPrint(){
  const settings={...printSettings(),download_mode:'link'};
  const capabilities=await api('/api/bootstrap');
  if(!capabilities.print_download_links||(settings.packaging==='per_page'&&!capabilities.print_page_links))throw new Error('Studio’s server needs a restart to download print files. Restart Studio with npm start, refresh this page, and try again.');
  const response=await fetch(state.printTray?'/api/print/pdf':`/api/decks/${state.printTarget?.deckId||state.printDeckContext?.deckId||state.deck.id}/print.pdf`,{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':state.token},body:JSON.stringify(settings)});
  if(!response.ok){const error=await response.json();throw new Error(error.error);}
  if(response.headers.get('content-type')?.split(';')[0].trim()!=='application/json'){await response.body?.cancel();throw new Error('The server returned an unexpected print format. Restart Studio, refresh this page, and export again.');}
  const result=await response.json();
  showPrintDownload(result,true);
  if(settings.packaging==='per_page'){toast('Print sheets are ready. Choose Open & print or Download for a sheet.');return;}
  const link=document.createElement('a');link.href=result.download_url;link.download=result.filename;
  document.body.appendChild(link);link.click();link.remove();
  toast('Print file is ready. Your browser download has started.');
}
function showPrintDownload(result,scroll=false){
  const ready=$('#print-download');if(!ready)return;
  if(!result){ready.hidden=true;ready.innerHTML='';return;}
  if(!/^\/api\/print-exports\/[a-f0-9-]+$/.test(result.download_url)||typeof result.filename!=='string')throw new Error('The server returned an invalid print download link.');
  const split=Array.isArray(result.pages)&&result.pages.length>0;
  if(split){
    if(!Array.isArray(result.pages)||!result.pages.length||result.pages.some(page=>!/^\/api\/print-exports\/[a-f0-9-]+\/pages\/\d+(?:\?view=1)?$/.test(page.view_url)||!/^\/api\/print-exports\/[a-f0-9-]+\/pages\/\d+$/.test(page.download_url)))throw new Error('The server returned invalid print page links.');
    if(ready){ready.hidden=false;ready.innerHTML=`<strong>Saved print sheets · up to date</strong><p>Open one sheet and press Ctrl+P. Print at Actual size / 100%.</p><ol class="print-page-links">${result.pages.map(page=>`<li><span>${esc(page.name)} · ${(page.size/1024**2).toFixed(1)} MB</span><a href="${esc(page.view_url)}" target="_blank" rel="noopener">Open &amp; print</a><a href="${esc(page.download_url)}" download="${esc(page.name)}">Download</a></li>`).join('')}</ol><p><a href="${esc(result.pages_url)}" target="_blank" rel="noopener">Open all page links in a new tab</a> · <a href="${esc(result.download_url)}" download="${esc(result.filename)}">Download ZIP</a></p>`;if(scroll)ready.scrollIntoView?.({block:'nearest'});}
    return;
  }
  if(ready){ready.hidden=false;ready.innerHTML=`<strong>Saved print file · up to date</strong><p><a href="${esc(result.download_url)}" download="${esc(result.filename)}">Download ${esc(result.filename)}</a></p>`;}
}
async function restorePrintHistory(){
  const form=$('#print-form'),settings=printSettings(),signature=JSON.stringify(settings);
  try{
    const previous=await api(state.printTray?'/api/print/history':`/api/decks/${state.printTarget?.deckId||state.printDeckContext?.deckId||state.deck.id}/print-history`,{method:'POST',body:settings});
    if($('#print-form')!==form||JSON.stringify(printSettings())!==signature)return;
    for(const [name,value] of Object.entries(previous.settings||{})){
      const input=form.elements[name];if(!input)continue;
      if(input.type==='checkbox')input.checked=value===true;else input.value=String(value);
    }
    showPrintDownload(previous.saved_export);
  }catch(e){if($('#print-form')===form)toast('Could not restore saved print files: '+e.message,true);}
}

