function deckBorders(){const d=state.deck,custom=d.cards.filter(c=>c.active_version_id&&c.art_mode!=='official'),inherits=c=>!JSON.parse(c.border_settings||'{}').style,creature=c=>/\bCreature\b/.test(c.summary?.faces?.[0]?.type_line||c.summary?.type_line||''),card=custom.find(c=>inherits(c)&&c.section==='commander')||custom.find(c=>inherits(c)&&creature(c))||custom.find(inherits)||custom[0];state.borderPreviewVersion=card?.active_version_id;modal('Deck outer borders',`<p class="form-intro">${esc(d.name)} · ${esc(d.art_set?.name||'Current artwork set')}</p><div class="border-dialog-grid"><div>${borderControls('deck',d.border_settings)}<details class="border-reference-guide"><summary>Real Magic references</summary><p class="field-hint">The outer border is separate from the coloured frame. Modern lower frames flare into black; borderless and extended-art treatments behave differently.</p><div class="border-reference-grid">${[['bordered','Modern black border'],['retro','Classic black border'],['legendary-bordered','Legendary frame'],['full-art-land','Full art with border'],['extended-art','Extended art'],['legendary-borderless','Borderless treatment'],['white-border','White border'],['silver-border','Silver border'],['gold-border','Gold border']].map(([key,label])=>`<a href="/frame-references/${key}-normal.jpg" target="_blank" rel="noopener"><img loading="lazy" src="/frame-references/${key}-thumb.jpg" alt="${esc(label)}"><span>${esc(label)}</span></a>`).join('')}</div><p class="field-hint">Sources: <a href="https://magic.wizards.com/en/news/feature/anatomy-magic-card-2006-10-21" target="_blank" rel="noopener">Wizards card anatomy</a> · <a href="https://magic.wizards.com/en/news/feature/magic-2015-core-set-release-notes-2014-07-07" target="_blank" rel="noopener">M15 frame update</a> · <a href="https://wpn.wizards.com/en/news/mark-rosewater-project-booster-fun" target="_blank" rel="noopener">Card treatments</a>.</p><p class="field-hint">Widths and curves are our adjustable presets, based on visual references, not unpublished Wizards manufacturing specifications.</p></details></div>${card?`<div class="border-live-preview"><img id="border-live-image" src="${imageUrl(card.active_version_id)}" alt="Outer border preview for ${esc(card.name)}"><p>${esc(card.name)}${inherits(card)?'':' · has its own border override'} · Changes save automatically</p></div>`:`<div class="border-live-preview"><img src="/frame-references/bordered-normal.jpg" alt="Standard bordered Magic card reference"><p>Standard bordered reference · Illustrate a custom card in ${esc(d.art_set?.name||'this artwork set')} to preview with your own art. Original Magic scans stay unchanged.</p></div>`}</div>`,true);}
