 if(state.frameEditor){state.frameVisualDraft=state.frameEditor.pack();state.frameEditor.dispose();state.frameEditor=null;}
 const versions=set.versions||[],chosen=versions.find(v=>v.id===state.framePreviewVersion&&v.status==='ready')||versions.find(v=>v.id===set.current_version_id)||versions.find(v=>v.status==='ready');
 const layout=state.frameLayout||'creature',family=state.frameColor||'G',legend=state.frameLegendary?'legendary':'normal',alias=state.frameAlias?'alias':'plain';
