 const structureRefs=(state.frameReferences?.references||[]).filter(r=>(layout==='saga'?['saga']:layout==='planeswalker'?['planeswalker','planeswalker-borderless']:layout==='land'?['full-art-land','extended-art']:layout.startsWith('transform')?['modal-dfc']:[]).includes(r.id));
