 const tabs=`<nav class="deck-tabs" aria-label="Card frame sections"><button class="${pageTab==='editor'?'active':''}" data-action="frame-page-tab" data-tab="editor">${icon('edit')} Editor</button><button class="${pageTab==='overview'?'active':''}" data-action="frame-page-tab" data-tab="overview">${icon('grid')} Overview & references</button></nav>`;
 const rail=`<aside class="frame-rail" aria-label="Preview context"><fieldset><legend>Card structure</legend><div class="structure-list">${set.layouts.map(k=>`<label><input type="radio" name="frame-layout" value="${k}" ${k===layout?'checked':''}><span>${k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase())}</span></label>`).join('')}</div></fieldset><fieldset><legend>Colour · ${esc(family.length===2?family:colourNames[family])}</legend><div class="colour-swatches">${['W','U','B','R','G','C','M'].map(swatch).join('')}</div><div class="colour-swatches pairs">${['WU','UB','BR','RG','GW','WB','UR','BG','RW','GU'].map(swatch).join('')}</div></fieldset><fieldset><legend>Variant</legend><div class="frame-preview-toggles"><label><input type="checkbox" id="frame-legendary" ${state.frameLegendary?'checked':''}><span>Legendary</span></label><label><input type="checkbox" id="frame-alias" ${state.frameAlias?'checked':''}><span>Alternate title</span></label><label><input type="checkbox" id="frame-real-art" ${state.frameRealArt?'checked':''}><span>Real artwork</span></label></div>${state.frameRealArt?`<div class="frame-real-art">${frameArtSetSelect()}<div data-frame-art>${frameArtCaption(layout)}</div></div>`:''}</fieldset>${structureRefs.length?`<div class="structure-references"><span class="field-hint">Printed-card references</span>${structureRefs.map(r=>`<a href="${esc(r.source_url)}" target="_blank" rel="noopener"><img loading="lazy" src="${r.thumb}" alt="${esc(r.label)}"><span>${esc(r.label)}</span></a>`).join('')}</div>`:''}${chosen?`<a class="text-button" href="${asset}${layout}.${family}.${legend}.${alias}.png" target="_blank" rel="noopener">Open saved version at full size ${icon('external')}</a>`:''}</aside>`;
 const sideTabs=`<div class="inspector-tabs drawer-tabs" role="tablist">${[['selection','Selection'],['notes','Notes'],['set','Frame settings']].map(([id,label])=>`<button role="tab" type="button" aria-selected="${side===id}" data-action="frame-inspector-tab" data-tab="${id}">${label}${id==='notes'&&state.frameVisualDraft?.visual_edits?.annotations?.length?` <span class="number-label">${state.frameVisualDraft.visual_edits.annotations.length}</span>`:''}</button>`).join('')}</div>`;
 const settingsForm=`<form id="frame-revision-form"><label>Set name<input name="name" maxlength="120" value="${esc(set.name)}" required></label>${frameDeckSourceForm(set.deck_art_set_id)}<label>Design brief<textarea name="brief" rows="8" maxlength="20000" required>${esc(set.brief)}</textarea></label>${frameBriefFields(set.brief_fields)}${frameControlsForm(set.controls||{},{hidePadding:true})}</form>`;
 const editor=chosen?`<div class="frame-editor-layout" id="frame-visual-editor">${rail}<section class="frame-canvas" data-fe-slot="canvas"></section><aside class="frame-inspector">${sideTabs}<div role="tabpanel" data-panel="selection" ${side==='selection'?'':'hidden'}><div data-fe-slot="inspector"></div></div><div role="tabpanel" data-panel="notes" ${side==='notes'?'':'hidden'}><div data-fe-slot="notes"></div></div><div role="tabpanel" data-panel="set" ${side==='set'?'':'hidden'}>${settingsForm}</div></aside></div>`:`<div class="frame-editor-layout pending"><section class="frame-canvas"><div class="empty-state"><h2>Your card frames are taking shape</h2><p>Previews appear when validation completes.</p></div></section><aside class="frame-inspector">${settingsForm}</aside></div>`;
 const savebar=`<div class="frame-savebar"><span data-frame-dirty>${frameDirtyLabel()}</span><p class="field-hint">Save keeps the name and options. Generating creates a new validated version; existing versions stay available.</p><button type="submit" form="frame-revision-form" value="save" class="button">Save settings</button>${frameOptionsToggle('form="frame-revision-form"')}<button type="submit" form="frame-revision-form" value="generate" class="button primary" ${busy?'disabled':''}>${icon('spark')} Generate new version</button></div>`;
 const overview=`<div class="frame-overview">${chosen?`<section><h3>All colours · normal and legendary</h3><a href="${asset}colour-matrix.jpg" target="_blank" rel="noopener"><img class="frame-matrix" loading="lazy" src="${asset}colour-matrix.jpg" alt="All 34 colour and legendary combinations"></a></section><section><h3>All required structures</h3><a href="${asset}contact-sheet.jpg" target="_blank" rel="noopener"><img class="frame-matrix" loading="lazy" src="${asset}contact-sheet.jpg" alt="Every required card structure"></a></section>`:'<div class="empty-state"><h2>No validated version yet</h2><p>Proof matrices appear when validation completes.</p></div>'}<section class="reference-library"><h3>Printed-card references</h3><p class="field-hint">Visual inspiration. Saga, Adventure and Battle structures require dedicated renderers and are not currently generated by this engine.</p><div class="reference-grid">${(state.frameReferences?.references||[]).map(r=>`<a class="frame-reference" href="${esc(r.source_url)}" target="_blank" rel="noopener"><img loading="lazy" src="${r.thumb}" alt="${esc(r.label)}"><span>${esc(r.label)}</span><small>${esc(r.artist)}</small></a>`).join('')}</div><p class="field-hint">${esc(state.frameReferences?.notice||'')}</p></section></div>`;
 if(set.template_source){const latest=versions[0];$('#content').innerHTML=`${header}<div class="frame-overview"><section><p class="field-hint">Drawn by Magic Set Editor from the Full Magic Pack template <b>${esc(set.template_source)}</b>, with the pack's official fonts. Normal cards, tokens and both faces of transforming cards use this template. Planeswalkers, sagas and adventures use the included frame.</p></section>${chosen?overview.replace(/<section class="reference-library">[\s\S]*<\/section><\/div>$/,'</div>'):latest?.status==='failed'?`<div class="empty-state"><h2>This template could not be rendered</h2><p class="error-copy">${esc((latest.error||'').slice(-600))}</p></div>`:'<div class="empty-state"><i class="spinner"></i><h2>Rendering every card type</h2><p>Magic Set Editor is drawing the previews. This takes a few minutes the first time a template is used.</p></div>'}</div>`;return;}
 // The settings form lives in the editor tab; keep it in the DOM (hidden) on the overview tab so the save bar still submits it.
