// Which artwork the real-art proof draws from: every deck, or one deck artwork set (default: the set that inspired this frame).
function frameArtSetId(){const set=state.frameDetail;state.frameArtSets??={};return set?.id in state.frameArtSets?state.frameArtSets[set.id]:(set?.deck_art_set_id||'');}
function frameArtSetSelect(){const selected=frameArtSetId();return `<label class="frame-art-set">Artwork from<select id="frame-art-set"><option value="">All decks</option>${(state.frameDeckSources||[]).filter(d=>d.art_sets.length).map(d=>`<optgroup label="${esc(d.name)}${d.archived?' (archived)':''}">${d.art_sets.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''} ${a.ready?'':'disabled'}>${esc(d.name)} · ${esc(a.name)}${a.ready?'':' · no art yet'}</option>`).join('')}</optgroup>`).join('')}</select></label>`;}
function frameArtCaption(layout){
 const art=state.frameArt?.layout===layout&&(state.frameArt.art_set_id||'')===frameArtSetId()?state.frameArt:null;if(state.frameArtError)return `<p class="error-copy">${esc(state.frameArtError)}</p>`;if(!art)return '<p class="field-hint">Choosing artwork…</p>';
 return `<p class="field-hint"><b>${esc(art.name)}</b> · ${esc(art.deck_name)}${art.matched?'':` <br>No ${esc(layout.replaceAll('_',' '))} art yet; using ${esc(art.matched_kind?art.matched_kind.replaceAll('_',' ')+' art':'any custom art')}.`}</p><button type="button" class="text-button" data-action="frame-shuffle-art" ${art.available>1?'':'disabled'}>${icon('refresh')} Shuffle</button>`;
}
// A random generated illustration suited to this structure replaces the placeholder in the live proof only.
async function pickFrameArt(layout,exclude=''){
 const request=state.frameArtRequest=(state.frameArtRequest||0)+1;state.frameArtError='';
 try{const art=await api(`/api/frame-sets/${encodeURIComponent(state.frameDetail.id)}/sample-art?layout=${encodeURIComponent(layout)}&exclude=${encodeURIComponent(exclude)}&art_set=${encodeURIComponent(frameArtSetId())}`);if(request!==state.frameArtRequest)return;state.frameArt=art;}
 catch(e){if(request!==state.frameArtRequest)return;state.frameArt=null;state.frameArtError=e.message;}
 const caption=$('[data-frame-art]');if(caption)caption.innerHTML=frameArtCaption(layout);if(state.frameArt?.layout===layout&&state.frameRealArt)state.frameEditor?.setArt(state.frameArt);
}
function showFrameInspectorTab(tab){state.frameInspectorTab=tab;for(const t of document.querySelectorAll('[data-action="frame-inspector-tab"]'))t.setAttribute('aria-selected',String(t.dataset.tab===tab));for(const p of document.querySelectorAll('.frame-inspector [role=tabpanel]'))p.hidden=p.dataset.panel!==tab;}
document.addEventListener('frame-editor-reveal',e=>showFrameInspectorTab(e.detail));
document.addEventListener('change',e=>{if(e.target.id==='frame-art-set'&&state.frameDetail){state.frameArtSets??={};state.frameArtSets[state.frameDetail.id]=e.target.value;state.frameArt=null;const caption=$('[data-frame-art]');if(caption)caption.innerHTML=frameArtCaption(state.frameLayout||'creature');void pickFrameArt(state.frameLayout||'creature');return;}const map={'frame-layout':'frameLayout','frame-colour':'frameColor','frame-legendary':'frameLegendary','frame-alias':'frameAlias','frame-real-art':'frameRealArt'};const key=map[e.target.id]||(e.target.type==='radio'&&map[e.target.name]);if(key){state[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;const form=$('#frame-revision-form'),draft=form?Object.fromEntries(new FormData(form)):null;renderFrameDetail();if(draft){for(const [k,v]of Object.entries(draft))if($('#frame-revision-form').elements[k])$('#frame-revision-form').elements[k].value=v;}}});
document.addEventListener('input',e=>{if(e.target.closest('#frame-revision-form')){state.frameDraftDirty=true;updateFrameDirty();}});
async function renderStylePage(){
 if(!state.bootstrap.styles_enabled){$('#content').innerHTML='<div class="empty-state"><h2>Styles is being installed</h2><p>The deck builder remains available. This page will be ready after the server update.</p></div>';return;}
 const request=state.stylePageRequest||0;$('#content').innerHTML='<div class="loading-state">Opening art direction…</div>';
 try{state.styleModule??=import('./style-studio.js?v=20261031-art-sets-1');const {StyleStudio}=await state.styleModule;if(request!==state.stylePageRequest)return;state.styleUI?.dispose();state.styleUI=new StyleStudio($('#content'),{api,toast,navigate:hash=>{location.hash=hash;},onSaved:()=>refresh().catch(e=>toast(e.message,true))});await state.styleUI.open(state.view==='styles'?'library':state.view==='style-detail'?'style':'deck',state.view==='style-detail'?state.styleId:state.deckId);if(request===state.stylePageRequest)renderShell();}catch(e){toast(e.message,true);}
}
function frameSelector(){
  const sets=state.frameSets.filter(s=>s.builtin||s.current_version_id),selected=state.deck.frame_set_id||'builtin-v2.4';
  return `<section class="deck-frame-selector"><label>Card frame for this deck<select id="deck-frame-set">${(sets.length?sets:[{id:'builtin-v2.4',name:'Bloomburrow inspired'}]).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><p class="field-hint">Changes save immediately and apply to newly queued jobs. Existing cards keep their frame until you re-apply it; that creates new versions from their current artwork without generating new art. Official printings keep their original frames. To re-frame only some custom cards, select them and choose Apply frame.</p><div class="frame-preview-heading"><h3>Preview with this deck’s artwork</h3><div class="segmented" role="group" aria-label="Preview comparison"><button class="active" data-action="frame-preview-view" data-view="frame" aria-pressed="true">With this frame</button><button data-action="frame-preview-view" data-view="current" aria-pressed="false">Current cards</button></div></div><div id="deck-frame-preview" class="deck-frame-preview" aria-live="polite"></div><div class="form-actions"><a class="button" href="#frames" data-action="close-modal">Browse card frames ${icon('arrow')}</a><button class="button primary" data-action="reframe-deck" data-scope="all">${icon('cards')} Apply to all current cards</button></div></section>`;
}
function setFramePreviewImage(img,src){
  const request=img.previewLoad=(img.previewLoad||0)+1,figure=img.closest('figure');
  figure.classList.remove('failed');figure.classList.add('loading');
  const loader=new Image();loader.decoding='async';
  const done=()=>{if(request!==img.previewLoad)return;img.src=src;figure.classList.remove('loading','failed');};
  loader.onload=done;loader.onerror=()=>{if(request!==img.previewLoad)return;figure.classList.remove('loading');figure.classList.add('failed');};
  loader.src=src;if(loader.complete&&loader.naturalWidth)done();
}
// One illustrated custom card per colour palette in the deck, plus a legendary card, recomposed with the chosen frame without saving versions.
async function loadFramePreview(frameSetId){
  const target=$('#deck-frame-preview');if(!target)return;const request=state.framePreviewRequest=(state.framePreviewRequest||0)+1,deckId=state.deck.id;
  target.innerHTML='<p class="field-hint">Choosing sample cards…</p>';
  try{
    const session=state.framePreviewSession||'';
    const result=await api(`/api/decks/${deckId}/frame-preview?frame_set_id=${encodeURIComponent(frameSetId)}&preview_session=${encodeURIComponent(session)}&preview_generation=${request}`);if(request!==state.framePreviewRequest||!$('#deck-frame-preview'))return;
    if(!result.samples.length){target.innerHTML='<p class="field-hint">Illustrate a custom card in this artwork set to preview frames with your own art. Original Magic scans keep their printed frames.</p>';return;}
    const revision=state.bootstrap?.border_revision?'&border_revision='+state.bootstrap.border_revision:'',current=$('[data-action="frame-preview-view"][data-view="current"]')?.classList.contains('active');
    target.innerHTML=result.samples.map(s=>{const framed=`/api/decks/${encodeURIComponent(deckId)}/frame-preview/${encodeURIComponent(s.card_id)}?frame_set_id=${encodeURIComponent(result.frame.id)}&frame_version=${encodeURIComponent(result.frame.version_id)}&version=${encodeURIComponent(s.version_id)}&preview_key=${encodeURIComponent(s.preview_key||'')}&preview_session=${encodeURIComponent(session)}${revision}`,existing=imageUrl(s.version_id,'thumb');return `<figure class="frame-preview-tile loading"><img src="${existing}" decoding="async" data-framed="${framed}" data-current="${existing}" alt="${esc(s.name)} with ${esc(current?'its current frame':result.frame.name)}"><figcaption><b>${esc(s.label)}</b>${esc(s.name)}</figcaption></figure>`;}).join('');
    target.querySelectorAll('img').forEach(img=>setFramePreviewImage(img,current?img.dataset.current:img.dataset.framed));
  }catch(e){if(request===state.framePreviewRequest&&$('#deck-frame-preview'))target.innerHTML=`<p class="error-copy">${esc(e.message)}</p>`;}
}
boot();
